Algorithm Precios
  Define precios As Vector<Integer> <- vector();
  Define leido As Integer;
  For i <- 1 To 5 Do
    Read leido;
    precios.append(leido);
  EndFor
  Define cambiados As Vector<Integer> <- vector();
  For Each precio In precios Do
    cambiados.append(precio + 1);
  EndFor
  Write cambiados;
  cambiados <- vector();
  For Each precio In precios Do
    cambiados.append(precio * 2);
  EndFor
  Write cambiados;
  cambiados <- vector();
  For Each precio In precios Do
    cambiados.append(precio - 1);
  EndFor
  Write cambiados;
EndAlgorithm

